# -*- coding: utf-8 -*-
"""Portable viewer for the two distinct stages of an actual benchmark run."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'outputs/sticker-benchmark-500'
data=json.loads((OUT/'results.json').read_text())
HTML=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>500 张表情包 · 语义候选与风格排序</title>
<style>
:root{--ink:#213b36;--muted:#64746d;--green:#276c57;--paper:#f4f5ef;--line:#dce3da;--blue:#285c85}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}header,main,footer{max-width:1400px;margin:auto;padding:32px}header{padding-top:54px}h1{font-size:38px;letter-spacing:-1px;line-height:1.3;margin:8px 0 14px}h2{font-size:23px;margin:0 0 12px}h3{font-size:17px;margin:8px 0}p{margin:8px 0}.eyebrow{font-size:13px;letter-spacing:2px;color:var(--green);font-weight:700}.muted,small{color:var(--muted)}.lead{max-width:1000px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0}.stat{background:white;padding:18px 22px;border:1px solid var(--line);border-radius:14px}.stat b{display:block;font-size:30px;color:var(--green)}.panel{background:#fff;border:1px solid var(--line);border-radius:18px;padding:24px;margin-bottom:22px}.toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:center}input,select,button{font:inherit;border:1px solid #c9d5cc;border-radius:9px;padding:10px 14px;background:white;color:var(--ink);max-width:100%}button{cursor:pointer}button:hover{background:#eef4ee}button.primary{background:var(--green);color:#fff;border-color:var(--green)}input{min-width:230px}select{flex:1;min-width:240px}label{font-size:14px;color:var(--muted)}.query{display:grid;grid-template-columns:170px 1fr;gap:24px;margin-top:20px;align-items:start}.query img{width:170px;height:170px;object-fit:contain;background:#f6f7f4;border-radius:12px}.tag{display:inline-block;font-size:12px;border-radius:5px;padding:2px 7px;background:#edf3ed;color:#325f48}.tag.blue{background:#e9f1f8;color:var(--blue)}.stages{display:grid;grid-template-columns:1fr 1fr;gap:22px;align-items:start}.stages .panel{min-width:0}.stage-title{display:flex;gap:12px;align-items:center}.step{border-radius:50%;height:35px;width:35px;line-height:35px;text-align:center;flex-shrink:0;background:var(--green);color:white;font-weight:bold}.stage1 .step{background:var(--blue)}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:18px;max-height:960px;overflow:auto;padding-right:4px}.card{border:1px solid var(--line);border-radius:12px;padding:13px;min-width:0}.card.best{border:2px solid var(--green);background:#f2f7f1}.card img{width:100%;height:160px;object-fit:contain;display:block;background:#f6f7f3;border-radius:8px;margin:10px 0}.card p{font-size:14px;line-height:1.5;word-break:break-word}.card .score{font-size:25px;font-weight:700;color:var(--green)}.card .hint{font-size:12px;color:var(--muted)}.card details{font-size:13px}.empty{padding:30px 14px;background:#f4f5f2;border-radius:10px;color:var(--muted)}.note{border-left:3px solid #bf965b;padding:12px 16px;background:#faf6ec;font-size:14px;margin:16px 0}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;border-bottom:1px solid var(--line);padding:10px}th{color:var(--muted)}details>summary{cursor:pointer;font-weight:600}a{color:var(--green)}footer{font-size:13px;padding-bottom:48px}.count{font-size:14px;color:var(--muted)}.gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(110px,1fr));gap:10px;max-height:620px;overflow:auto;margin-top:16px}.gallery button{padding:7px;font-size:12px;line-height:1.4}.gallery img{width:100%;height:88px;object-fit:contain;display:block}.legend{font-size:14px}.summary-text{font-size:17px}.downloads{display:flex;gap:10px;flex-wrap:wrap}pre{white-space:pre-wrap;word-break:break-all;font-size:12px}
@media(max-width:850px){header,main,footer{padding:20px}header{padding-top:30px}h1{font-size:29px}.stages{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.panel{padding:18px}.query{grid-template-columns:100px 1fr;gap:14px}.query img{width:100px;height:100px}.cards{max-height:650px}.card img{height:140px}}
</style>
<header><div class="eyebrow">XIAOYU · 500-IMAGE BENCHMARK</div><h1>先找相近意思，再比较表达风格</h1><p class="lead">500 张网络表情包逐张作为查询图。左侧是语义筛选候选，右侧将<strong>同一批候选</strong>按风格差异从大到小排序。可切换任意图片，检查两个阶段的完整结果。</p><div id="stats" class="stats"></div><p id="overview" class="summary-text"></p><div class="note"><strong>这是实际模型运行结果，不是模拟分数。</strong>语义描述来自豆包视觉模型，筛选使用 BGE 中文文本嵌入；“候选”仍需结合聊天语境核对，不代表已证明同义。风格使用作者公开 ALADIN-ViT 权重。<strong>本次没有运行或训练 GSE，也没有改动正式被试图库。</strong></div></header>
<main>
<section class="panel"><div class="toolbar"><label for="search">查找表情</label><input id="search" placeholder="输入含义、文字、系列或编号"><select id="query" aria-label="查询表情"></select><label for="threshold">语义门槛</label><select id="threshold" style="flex:0;min-width:130px"><option value=".75">0.75 · 原程序初值</option><option value=".8">0.80</option><option value=".85">0.85</option><option value=".9">0.90</option></select><button id="next">下一张</button></div><div id="queryCard" class="query"></div></section>
<div class="stages"><section class="panel stage1"><div class="stage-title"><span class="step">1</span><h2>语义相近 / 同义候选</h2></div><p class="legend">按语义余弦相似度从高到低展示。仅比较“含义”描述；画风与主体不进入此分数。</p><p id="count1" class="count"></p><div id="stage1" class="cards"></div></section><section class="panel"><div class="stage-title"><span class="step">2</span><h2>候选内的风格差异排序</h2></div><p class="legend">风格距离 = 1 − ALADIN 特征余弦相似度。数值越大，模型中的风格差异越大。</p><p id="count2" class="count"></p><div id="stage2" class="cards"></div></section></div>
<section class="panel"><h2>语义门槛会改变可选范围</h2><p class="muted">这些门槛用于敏感性检查，尚未以人工金标准校准。提高门槛不等于保证同义，也不会重新计算风格特征。</p><div style="overflow:auto"><table><thead><tr><th>门槛</th><th>有候选的查询图</th><th>无向候选图片对</th><th>每图候选中位数</th><th>最多候选</th></tr></thead><tbody id="sensitivity"></tbody></table></div></section>
<section class="panel"><details><summary>查看全部 500 张测试图片</summary><p class="muted">点击缩略图切换查询。每张图都参与过测试；页面不会只展示效果好的案例。</p><div id="gallery" class="gallery"></div></details></section>
<section class="panel"><h2>保存两阶段结果</h2><div class="downloads"><button id="downloadOne" class="primary">下载当前图片两阶段结果</button><button id="downloadStage1">下载全部阶段 1（0.75）</button><button id="downloadStage2">下载全部阶段 2（0.75）</button><button id="downloadManifest">下载来源与方法</button></div></section>
<section class="panel"><details><summary>数据来源、算法版本与解释边界</summary><div id="methods"></div></details></section>
</main><footer>小屿 · 离线算法测试 · 2026-11-11。素材来源 <a href="https://github.com/zhaoolee/ChineseBQB" target="_blank" rel="noopener">ChineseBQB</a>，图像权利归各自原作者。网络素材测试不等同于正式实验刺激验证。</footer>
<script id="dataset" type="application/json">__DATA__</script>
<script>
'use strict';const DATA=JSON.parse(document.getElementById('dataset').textContent),S=DATA.summary,byId=Object.fromEntries(DATA.items.map(r=>[r.id,r]));const $=id=>document.getElementById(id);
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}function image(r){const n=el('img');n.src=r.thumbnail;n.alt=r.ocr||r.meaning;n.loading='lazy';return n}
for(const [v,t] of [[S.images,'真实图片'],[S.source_series,'来源系列'],[S.queries_with_candidates,'存在语义候选的查询'],[S.unique_pairs,'无向候选图片对']]){const n=el('div',undefined,'stat');n.append(el('b',v),el('span',t));$('stats').append(n)}
$('overview').textContent=`默认门槛 0.75 下，${S.queries_with_candidates} / 500 张图有候选，${S.queries_without_candidates} 张没有候选；每张图的候选中位数为 ${S.median_candidates}。无候选时保留空结果，不降低门槛凑数。`;
function filter(){const term=$('search').value.trim().toLowerCase(),previous=$('query').value;$('query').replaceChildren();for(const r of DATA.items){if(term&&!`${r.id} ${r.meaning} ${r.ocr} ${r.pack}`.toLowerCase().includes(term))continue;const o=el('option',`${r.id} · ${r.meaning.slice(0,44)}`);o.value=r.id;$('query').append(o)}if([...$('query').options].some(o=>o.value===previous))$('query').value=previous;render()}
function selected(){const id=$('query').value,t=Number($('threshold').value),v=DATA.queries[id];if(!v)return null;const r=v.stage2.filter(x=>x.semantic_score>=t);return {id,t,style:r,semantic:[...r].sort((a,b)=>b.semantic_score-a.semantic_score||a.id.localeCompare(b.id))}}
function card(r,index,stage){const item=byId[r.id],c=el('article',undefined,'card'+(stage===2&&index===0?' best':''));c.append(el('span',stage===2&&index===0?'本次候选最大风格差异':`第 ${index+1} 名 · ${r.id}`,'tag'+(stage===1?' blue':'')),image(item),el('p',item.meaning),el('div',(stage===1?r.semantic_score:r.style_distance).toFixed(4),'score'),el('div',stage===1?'语义余弦相似度':`风格距离 · 语义 ${r.semantic_score.toFixed(4)}`,'hint'));const d=el('details'),a=el('a','查看来源原图');a.href=item.source;a.target='_blank';a.rel='noopener';d.append(el('summary','含义与歧义依据'),el('p','文字：'+(item.ocr||'无可辨识文字')),el('p','情境：'+item.situation),el('p','歧义：'+item.ambiguity),el('p','视觉风格：'+item.style),a);c.append(d);return c}
function render(){const v=selected();$('queryCard').replaceChildren();$('stage1').replaceChildren();$('stage2').replaceChildren();if(!v){$('queryCard').append(el('p','没有匹配图片，请换一个关键词。'));$('count1').textContent='';$('count2').textContent='';return}const r=byId[v.id],text=el('div');text.append(el('span',v.id+' · 查询图','tag'),el('h3',r.meaning),el('p','图片文字：'+(r.ocr||'无可辨识文字')),el('p','适用情境：'+r.situation),el('small','可能歧义：'+r.ambiguity));$('queryCard').append(image(r),text);$('count1').textContent=`${v.semantic.length} 张候选 · 门槛 ${v.t.toFixed(2)} · 排除查询图和近重复图`;$('count2').textContent=v.style.length?`相同的 ${v.style.length} 张候选 · 最大距离 ${v.style[0].style_distance.toFixed(4)}`:'没有合格语义候选，因此不进行风格推荐';for(const [id,list,stage] of [['stage1',v.semantic,1],['stage2',v.style,2]]){if(!list.length)$(id).append(el('p','此查询在当前门槛下无合格候选。','empty'));else list.forEach((r,i)=>$(id).append(card(r,i,stage)))} }
$('search').addEventListener('input',filter);$('query').addEventListener('change',render);$('threshold').addEventListener('change',render);$('next').onclick=()=>{const q=$('query');if(q.options.length)q.selectedIndex=(q.selectedIndex+1)%q.options.length;render()};
for(const r of S.sensitivity){const tr=el('tr');for(const v of [r.threshold.toFixed(2),`${r.queries_with_candidates} / 500`,r.unique_pairs,r.median_candidates,r.max_candidates])tr.append(el('td',v));$('sensitivity').append(tr)}
for(const r of DATA.items){const b=el('button');b.append(image(r),el('span',r.id));b.title=r.meaning;b.onclick=()=>{$('search').value='';filter();$('query').value=r.id;render();$('queryCard').scrollIntoView({behavior:'smooth',block:'center'})};$('gallery').append(b)}
function download(name,obj){const a=el('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('downloadOne').onclick=()=>{const v=selected();if(v)download(v.id+'-two-stages.json',{query:byId[v.id],threshold:v.t,stage1:v.semantic,stage2:v.style,limitations:DATA.limitations})};
$('downloadStage1').onclick=()=>download('stage1-semantic-candidates.json',Object.fromEntries(Object.entries(DATA.queries).map(([id,q])=>[id,{meaning:byId[id].meaning,candidates:[...q.stage2].sort((a,b)=>b.semantic_score-a.semantic_score).map(r=>({id:r.id,meaning:byId[r.id].meaning,semantic_score:r.semantic_score}))}])));
$('downloadStage2').onclick=()=>download('stage2-style-ranking.json',Object.fromEntries(Object.entries(DATA.queries).map(([id,q])=>[id,q.stage2])));
$('downloadManifest').onclick=()=>download('benchmark-methods.json',{summary:S,dataset:DATA.dataset,provenance:DATA.provenance,limitations:DATA.limitations});
$('methods').append(el('p',`采样：${DATA.dataset.sampling}。固定种子 ${DATA.dataset.seed}，提交 ${DATA.dataset.commit}。`),el('p',`实际排除 ${S.excluded_near_duplicate_pairs} 对近重复图；500 张原始文件与来源清单另存。`),el('p','本次仅运行推理，没有用这 500 张图训练任何模型。图像全画面缩放与白底透明合成后送入固定 ALADIN 权重；BGE 只读取独立含义字段。'),el('p','每张图作为查询，对其余图片进行比较；同一图片对的风格距离对称，因此无向图片对按两条查询方向记录。不同查询的候选集合可重叠，不是互斥语义分类。'));
for(const t of DATA.limitations)$('methods').append(el('p','• '+t));$('methods').append(el('pre',JSON.stringify(DATA.provenance,null,2)));
filter();const examples=DATA.items.filter(r=>/感谢|谢谢|收到|明白|拥抱|困了|晚安/.test(r.meaning)&&DATA.queries[r.id].stage2.length>=3);if(examples.length){$('query').value=examples[0].id;render()}
</script></html>'''
(OUT/'500表情包_两阶段测试.html').write_text(HTML.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c')))
print('Rendered',OUT/'500表情包_两阶段测试.html')
